NS_IMETHODIMP ExchangeFolder::CopyFileMessage(
    nsIFile* aFile, nsIMsgDBHdr* msgToReplace, bool isDraftOrTemplate,
    uint32_t newMsgFlags, const nsACString& aNewMsgKeywords,
    nsIMsgWindow* msgWindow, nsIMsgCopyServiceListener* copyListener) {
  // Ensure both a source file and a listener have been provided.
  NS_ENSURE_ARG_POINTER(aFile);
  NS_ENSURE_ARG_POINTER(copyListener);

if (mSrcFile) {
  // When creating a message from a file, we expect this to be one part of a
  // larger operation (such as saving a draft message). As such,
  // `mCopyServiceListener` must be non-null so we can signal completion of
  // the copy operation. This isn't necessarily the case when copying from a
  // folder, where the copy may be the only action being performed.
  NS_ENSURE_ARG_POINTER(mCopyServiceListener);

  // We've already got the message's content, so no need to CopyMessage()
  // from elsewhere.
  nsCOMPtr<nsIInputStream> srcRaw;
  nsCOMPtr<nsIFile> file(mSrcFile.value());
  nsresult rv = NS_NewLocalFileInputStream(getter_AddRefs(srcRaw), file);
  NS_ENSURE_SUCCESS(rv, rv);

  // When creating a message from a file, we're saving to either the Sent
  // folder (in which case we mark the message as read) or to the Draft folder
  // (in which case we mark the message as unread).
  bool isRead = !mIsDraft;

  return ExchangePerformMessageCreate(
      mDstFolder, srcRaw, isRead, mIsDraft,
      [self = RefPtr(this)](nsresult status, nsIMsgDBHdr* newHdr) {
        self->OnCreateFinished(status, newHdr);
      });

const copyListener = new PromiseTestUtils.PromiseCopyListener();
MailServices.copy.copyFileMessage(
  do_get_file("../../../../test/data/bugmail11"),
  folder,
  null,
  false,
  0, // message flags
  "$label4", // keywords
  copyListener,
  null // window
);
const copied = await copyListener.promise;

// Check the copied message.

const header = folder.GetMessageHeader(copied.messageKeys[0]);
Assert.equal(
  header.messageId,
  "200804111417.m3BEHTk4030129@mrapp51.mozilla.org",
  "copied message's Message-ID is set from the message"
);
Assert.ok(
  header.getStringProperty("ewsId"),
  "copied message should have been assigned an EWS ID"
);
Assert.ok(
  header.storeToken,
  "copied message should have been stored on disk"
);
// TODO:
// Assert.equal(
//   header.getStringProperty("keywords"),
//   "$label4",
//   "keywords should have been set in the database"
// );

// Check the message is on the server;

const serverMessage = ewsServer.getItem(header.getStringProperty("ewsId"));
Assert.ok(serverMessage);
Assert.equal(serverMessage.parentId, "copyFileMessage");
